using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute.", "Bake for 10-12 minutes.", "Top with fresh basil and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Creamy, spiced tomato sauce with tender chicken pieces.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté garlic and ginger in oil.", "Add tomato sauce and spices, simmer 15 min.", "Stir in cream and cooked chicken.", "Serve over basmati rice."],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 min.", "Warm taco shells in oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
            AverageRating = 4.2, RatingCount = 18
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water 30 min.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in wok.", "Add noodles, tamarind paste, fish sauce, and sugar.", "Toss with shrimp, bean sprouts, and green onions.", "Serve with crushed peanuts and lime wedge."],
            AverageRating = 4.6, RatingCount = 31
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cake with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs.", "Add flour and vanilla, mix gently.", "Pour into greased ramekins, bake 12-14 min."],
            AverageRating = 4.9, RatingCount = 56
        },
        new()
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Description = "Crisp romaine lettuce with creamy Caesar dressing and croutons.",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Caesar dressing", "Lemon juice", "Anchovy paste"],
            Steps = ["Wash and chop romaine lettuce.", "Whisk dressing with lemon juice and anchovy paste.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons.", "Serve immediately."],
            AverageRating = 4.0, RatingCount = 15
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = [];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetRecipe(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count + 20; // include seed ratings
        recipe.AverageRating = Math.Round(
            (_ratings[recipeId].Sum() + recipe.AverageRating * 20) / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted recipe for {submission.Title}.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

