            Steps = ["Soak rice noodles in warm water 30 min.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in wok.", "Add noodles, tamarind paste, fish sauce, and sugar.", "Toss with shrimp, bean sprouts, and green onions.", "Serve with crushed peanuts and lime wedge."],
            AverageRating = 4.6, RatingCount = 31
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cake with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs.", "Add flour and vanilla, mix gently.", "Pour into greased ramekins, bake 12-14 min."],
            AverageRating = 4.9, RatingCount = 56
        },
        new()
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Description = "Crisp romaine lettuce with creamy Caesar dressing and croutons.",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Caesar dressing", "Lemon juice", "Anchovy paste"],
            Steps = ["Wash and chop romaine lettuce.", "Whisk dressing with lemon juice and anchovy paste.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons.", "Serve immediately."],
            AverageRating = 4.0, RatingCount = 15
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = [];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetRecipe(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(
            ((recipe.AverageRating * (recipe.RatingCount - 1)) + stars) / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted recipe for {submission.Title}.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

