@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>📝 Submit Your Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe has been submitted successfully.
        <a href="/">Return to Home</a>
    </div>
}
else
{
    <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Asian">Asian</option>
                <option value="Desserts">Desserts</option>
                <option value="Salads">Salads</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_submission.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_submission.Steps"
                placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
        </div>

        <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.RecipeSubmission _submission = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_submission.Title) || string.IsNullOrWhiteSpace(_submission.Category))
            return;

        RecipeService.SubmitRecipe(_submission);
        _submitted = true;
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <p>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => _hoveredStar = star"
                  @onmouseout="() => _hoveredStar = 0"
                  style="cursor: pointer; font-size: 2rem;">
                @(star <= (_hoveredStar > 0 ? _hoveredStar : _selectedStar) ? "★" : "☆")
            </span>
        }
    </p>
    <p class="text-muted">
        @if (_selectedStar > 0)
        {
            <span>You rated this @_selectedStar out of 5. </span>
        }
        Average: @CurrentRating / 5 (@RatingCount ratings)
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private int _hoveredStar;
    private int _selectedStar;

    private void Rate(int stars)
    {
        _selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

