{"file_text": "@rendermode InteractiveServer

<div class="star-rating">
    <p>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => _hoveredStar = star"
                  @onmouseout="() => _hoveredStar = 0"
                  style="cursor: pointer; font-size: 2rem;">
                @(star <= (_hoveredStar > 0 ? _hoveredStar : _selectedStar) ? "★" : "☆")
            </span>
        }
    </p>
    <p class="text-muted">
        @if (_selectedStar > 0)
        {
            <span>You rated this @_selectedStar out of 5. </span>
        }
        Average: @CurrentRating / 5 (@RatingCount ratings)
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private int _hoveredStar;
    private int _selectedStar;

    private void Rate(int stars)
    {
        _selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}
